def ring_reward(rewards):
    n = len(rewards)
    if n == 0:
        return [0, 1]
    if n == 1:
        if rewards[0] == 0:
            return [0, 2]
        if rewards[0] > 0:
            return [rewards[0], 1]
        return [0, 1]
    off = straight_row(rewards, 1, n)
    on = straight_row(rewards, 2, n - 1)
    on[0] += rewards[0]
    if on[0] == off[0]:
        return [on[0], on[1] + off[1]]
    if on[0] > off[0]:
        return on
    return off
def straight_row(rewards, left, stop):
    prev = [0, 1]
    older = [0, 1]
    for i in range(left, stop):
        take = older[0] + rewards[i]
        best = prev
        if take > prev[0]:
            best = [take, older[1]]
        elif take == prev[0]:
            best = [take, older[1] + prev[1]]
        older = prev
        prev = best
    return prev

